import sys

def process_spell(input_text):
    lines = input_text.split('\n')
    result = []
    current_line = ''
    for line in lines:
        stripped_line = line.lstrip()
        if stripped_line.startswith('#'):
            if current_line:
                result.append(current_line)
                current_line = ''
            result.append(line)
        else:
            current_line += ''.join(stripped_line.split())
    if current_line:
        result.append(current_line)
    return '\n'.join(result) + '\n'

input_text = sys.stdin.read()
print(process_spell(input_text))
